	const wchar_t* ModuleParserRuleName(vl::vint index)
	{
		static const wchar_t* results[] = {
			L"_Name",
			L"_PrimitiveShared",
			L"_PrimitiveTypeOnly",
			L"_PrimitiveExprOnly",
			L"_LongType",
			L"_Expr0",
			L"_Expr1",
			L"_Expr2",
			L"_ExprNoComma",
			L"_Expr",
			L"Module",
			L"ExprModule",
			L"TypeModule",
		};
		return results[index];
	}

